jQuery(document).ready(function($) {
        // Create the dropdown div
    var dropdown = $('<div class="msls-dropdown"></div>');
    
    // Wrap the non-current languages with the dropdown div
    $('.msls a:not(.current_language)').wrapAll(dropdown);
    // Remove the href attribute from the current language link
    $('.msls .current_language').removeAttr('href');
    
    // Toggle the dropdown on clicking the current language
    $('.msls .current_language').on('click', function() {
        $('.msls-dropdown').toggle();
    });

    // Hide the dropdown when clicking outside
    $(document).on('click', function(e) {
        var container = $(".msls");
        if (!container.is(e.target) && container.has(e.target).length === 0) {
            $('.msls-dropdown').hide();
        }
    });
});

$('#billings-modal-btn').on('click', function () {
    $('#billings-modal').detach().appendTo('body');

    $('#billings-modal').css({
        display: "flex"
    });
});

$('#billings-modal .billings-modal__bg').on('click', function () {
    $('#billings-modal').css({
        display: ""
    });

    $('#billings-modal').detach().appendTo('#billings-modal-btn');
});
$('#billings-modal .billings-modal--close').on('click', function () {
    $('#billings-modal').css({
        display: ""
    });

    $('#billings-modal').detach().appendTo('#billings-modal-btn');
});

$('.billings-modal__content-items__item-dropdown-head-title').on('click', function(){
    $(this).closest('.billings-modal__content-items__item-dropdown').toggleClass('billings-modal__content-items__item-dropdown--active')
});

